(1, 'Pokémon Radical Red', 'Un repte només per als millors entrenadors. Megaevolucions i dificultat extrema.', 0.00, 'media/pkmn_red_g.jpg', 'media/pkmn_red_p.jpg'),
(2, 'Pokémon Eternal X', 'Reviu Kalos amb un nivell de dificultat completament ajustat i tots els Pokémon disponibles.', 0.00, 'media/pkmn_x_g.jpg', 'media/pkmn_x_p.jpg'),
(3, 'EA FC 24', 'Agafa el teu FC Barcelona i porta\'l al cim d\'Europa en el simulador de futbol definitiu.', 69.99, 'media/eafc_g.jpg', 'media/eafc_p.jpg'),
