DELIMITER $$
--
-- Procediments
--
CREATE DEFINER=`root`@`%` PROCEDURE `EmplenarCatalegDefinitiu` ()   BEGIN
    DECLARE i INT DEFAULT 21;
    DECLARE joc_id INT;
    DECLARE rand_user INT;
    DECLARE rand_genere INT;
    DECLARE rand_creador INT;
    
    WHILE i <= 1200 DO
        SELECT id_usuari INTO rand_user FROM usuaris ORDER BY RAND() LIMIT 1;
        SELECT id_genere INTO rand_genere FROM generes ORDER BY RAND() LIMIT 1;
        SELECT id_creador INTO rand_creador FROM creadors ORDER BY RAND() LIMIT 1;

        VALUES (
            CONCAT('Joc Generat ', i), 
            'Aquesta és una descripció de prova generada pel servidor per tenir volum de dades.', 
            ROUND(RAND() * (79.99 - 4.99) + 4.99, 2),
            'media/default_gran.jpg', 
            'media/default_petit.jpg'
        );
        
        SET joc_id = LAST_INSERT_ID();

        VALUES (joc_id, rand_genere);

        VALUES (joc_id, rand_creador);
        
        VALUES (
            rand_user, 
            joc_id, 
            FLOOR(RAND() * (100 - 30) + 30),
            'Valoració automatitzada per omplir la base de dades.'
        );

        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

